--
-- Table structure for table `tbl_plots`
--

DROP TABLE IF EXISTS `tbl_plots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_plots` (
  `plot_id` int(11) NOT NULL AUTO_INCREMENT,
  `section` varchar(10) NOT NULL,
  `row` int(11) NOT NULL,
  `plot_number` int(11) NOT NULL,
  `plot_x` int(11) NOT NULL,
  `plot_y` int(11) NOT NULL,
  `lawn_type` varchar(100) DEFAULT NULL,
  `price` decimal(10,2) DEFAULT 0.00,
  `status` enum('available','reserved','occupied') DEFAULT 'available',
  PRIMARY KEY (`plot_id`),
  UNIQUE KEY `uniq_section_row_plot` (`section`,`row`,`plot_number`)
) ENGINE=InnoDB AUTO_INCREMENT=1229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

